with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('gå på pension', 'phrase', 'd1e41a5f-96c4-540c-b595-ae70e630f21c', 1, 'verb', null, 'виходити на пенсію', 'Min far gik på pension sidste år.', 'Мій батько вийшов на пенсію минулого року.'), ('være sammen', 'phrase', '0079a5c6-a94b-50b1-a09e-0f4e6df66c82', 1, 'verb', null, 'бути разом (у стосунках)', 'De har været sammen i tre år.', 'Вони разом уже три роки.'), ('være sammen', 'phrase', '04607ac2-07b8-55b3-bcb4-d557c6aa06d1', 2, 'verb', null, 'бути разом (проводити час)', 'Børnene er sammen hver dag efter skole.', 'Діти разом щодня після школи.'), ('slå op', 'phrase', 'd2b28152-fa62-59d1-acdb-f6221da804c6', 1, 'verb', null, 'розходитися (з партнером)', 'De slog op efter tre år sammen.', 'Вони розійшлися після трьох років разом.'), ('holde øje med', 'phrase', 'd15c26d3-ee46-55c1-a57c-7d83275ed8a9', 1, 'verb', null, 'стежити за', 'Kan du holde øje med min taske mens jeg henter kaffe?', 'Можеш приглянути за моєю сумкою, поки я заберу каву?'), ('gå tur', 'phrase', '8dff40f3-c4fa-5c6e-9250-f50e221c0432', 1, 'verb', null, 'гуляти (пішки)', 'Vi gik tur langs stranden i aftes.', 'Вчора ввечері ми гуляли вздовж пляжу.'), ('blive til virkelighed', 'phrase', 'f4061e29-5609-5397-b919-5cf9351bb753', 1, 'verb', null, 'збуватися, ставати реальністю', 'Drømmen om et hus ved havet blev til virkelighed sidste år.', 'Мрія про будинок біля моря стала реальністю минулого року.'), ('på trods af', 'phrase', 'ec3f9a65-02fc-50f5-9a66-23b342e9767a', 1, 'preposition', null, 'незважаючи на', 'På trods af regnen gik vi en tur.', 'Незважаючи на дощ, ми пішли на прогулянку.'), ('træde tilbage', 'phrase', 'f6bc78be-1002-5bf4-bc4c-6c38c86b59a1', 1, 'verb', null, 'відступати (фізично)', 'Han trådte tilbage for at give plads.', 'Він відступив, щоб звільнити місце.'), ('forberede sig', 'phrase', 'e59d1284-02a2-54d5-8df9-2f107a01d87a', 1, 'verb', null, 'готуватися', 'Hun forberedte sig til eksamen hele weekenden.', 'Вона готувалася до іспиту весь вікенд.'), ('klage over', 'phrase', '742301fe-06a1-5af8-adf9-6964875a525e', 1, 'verb', null, 'скаржитися на', 'Hun klager over maden hver dag.', 'Вона щодня скаржиться на їжу.'), ('godt nytår', 'phrase', '8e1fdaf3-806a-5ae5-9587-9e977b6c0b3d', 1, 'phrase', null, 'з Новим роком', 'Jeg ønsker dig et godt nytår.', 'Бажаю тобі щасливого Нового року.'), ('vaske sig', 'phrase', '4bebe940-76ef-57e1-844c-a9f1575dcf82', 1, 'verb', null, 'митися', 'Jeg vasker mig hver morgen.', 'Я миюся щоранку.'), ('skrive under', 'phrase', 'e90f14f0-3c45-5486-acd1-5ecbd12ee8f3', 1, 'verb', null, 'підписувати', 'Hun skrev under på kontrakten i går.', 'Вона підписала контракт учора.'), ('falde sammen', 'phrase', '45405a9b-00f7-53e4-b6cb-4bebe5721e12', 1, 'verb', null, 'руйнуватися (про будівлю)', 'Det gamle hus faldt sammen under stormen.', 'Старий будинок обвалився під час бурі.'), ('prøve på', 'phrase', '35877699-321f-524d-b2c6-51549287b033', 1, 'verb', null, 'намагатися (щось зробити)', 'Hun prøver på at lære dansk.', 'Вона намагається вивчити данську.'), ('skifte mening', 'phrase', 'ada1c133-59a3-52be-96eb-f295f6a5a1dd', 1, 'verb', null, 'передумати', 'Jeg skiftede mening om filmen efter at have set den igen.', 'Я передумав щодо фільму після повторного перегляду.'), ('kigge ud', 'phrase', '4fdb8279-a664-5464-8b94-3d6d2e7e6d1c', 1, 'verb', null, 'виглядати (назовні)', 'Han kigger ud ad vinduet hver morgen.', 'Він щоранку дивиться у вікно.'), ('interessere sig for', 'phrase', '755f0811-09e3-555a-ab3b-559a1cc9800a', 1, 'verb', null, 'цікавитися (чимсь)', 'Hun interesserer sig for dansk historie.', 'Вона цікавиться данською історією.'), ('sørge for', 'phrase', '1a617e1d-6d55-5514-81a7-f819b64545d4', 1, 'verb', null, 'забезпечувати, дбати про те, щоб', 'Jeg sørger for, at døren er låst.', 'Я стежу, щоб двері були зачинені.'), ('sørge for', 'phrase', '71fe7ce9-3dc4-55d5-8eb8-ee3247f5b918', 2, 'verb', null, 'організовувати, влаштовувати (щось)', 'De sørgede for mad til alle gæsterne.', 'Вони забезпечили їжею всіх гостей.'), ('blande sig', 'phrase', '5af57b52-d8cb-564a-9da0-372ef9e1f9f1', 1, 'verb', null, 'втручатися', 'Hun blander sig altid i vores samtaler.', 'Вона завжди втручається у наші розмови.'), ('indflydelse på', 'phrase', '15632443-1080-5854-abb2-5b8345037241', 1, 'phrase', null, 'вплив на', 'Hendes mening har stor indflydelse på beslutningen.', 'Її думка має великий вплив на рішення.'), ('holde jul', 'phrase', 'c7be6092-f903-5b72-8472-4723bf224d6c', 1, 'verb', null, 'святкувати Різдво', 'Vi holder jul hos mine forældre i år.', 'Цього року ми святкуємо Різдво у моїх батьків.'), ('blive skilt', 'phrase', 'b4cb5fa4-179f-5433-9a4d-084ffc22417b', 1, 'verb', null, 'розлучатися', 'De blev skilt efter ti års ægteskab.', 'Вони розлучилися після десяти років шлюбу.'), ('begå selvmord', 'phrase', 'fd8d83e3-3a20-5f26-a31a-47453f5d49a8', 1, 'verb', null, 'вчиняти самогубство', 'Hun begik selvmord efter en lang depression.', 'Вона покінчила життя самогубством після тривалої депресії.'), ('holde kæft', 'phrase', 'abf606fe-c06f-5eb1-ae88-a99d24c07f1c', 1, 'verb', null, 'заткнутися (грубо)', 'Hold kæft og lyt til læreren.', 'Замовкни і слухай вчителя.'), ('se frem til', 'phrase', 'b122dd1f-26dd-56dc-a1ee-5d534cc8a93c', 1, 'verb', null, 'чекати з нетерпінням', 'Jeg ser frem til ferien.', 'Я з нетерпінням чекаю свят.'), ('få at vide', 'phrase', 'ff245af3-0ed8-56fe-a33f-5766a26d8973', 1, 'verb', null, 'дізнаватися (отримувати інформацію)', 'Jeg fik at vide, at mødet er aflyst.', 'Мені сказали, що зустріч скасована.'), ('klare sig', 'phrase', 'cc1e69d5-1820-57b3-8c64-73233173bc52', 1, 'verb', null, 'справлятися', 'Jeg tror, at hun klarer sig fint på det nye job.', 'Думаю, вона добре впорається на новій роботі.'), ('høre efter', 'phrase', 'b5734c26-6ae0-503c-b222-96f57c8fc193', 1, 'verb', null, 'слухати (уважно)', 'Børnene hører efter, når læreren taler.', 'Діти слухають, коли вчитель говорить.'), ('falde ned', 'phrase', 'fe663d58-7521-5bb9-bad5-99e4bbc67c6d', 1, 'verb', null, 'падати (вниз)', 'Bogen faldt ned fra bordet.', 'Книга впала зі столу.'), ('vende tilbage til', 'phrase', 'e758595f-3619-5fff-9b7c-ce67b424e317', 1, 'verb', null, 'повертатися (до теми, місця)', 'Vi vender tilbage til emnet i morgen.', 'Завтра ми повернемося до теми.'), ('gå væk', 'phrase', '4d68f3d3-6f15-5b25-88c9-59a65123bd06', 1, 'verb', null, 'зникати (про пляму, біль)', 'Pletten på skjorten gik væk i vask.', 'Пляма на сорочці зникла під час прання.'), ('løbe ud', 'phrase', '070ed4a8-9a73-5f8e-8683-50efd577741c', 1, 'verb', null, 'закінчуватися (про термін)', 'Mit pas løb ud i sidste uge.', 'Термін дії мого паспорта закінчився минулого тижня.'), ('løbe ud', 'phrase', 'bf6ee3f4-5031-52ec-b21c-139bca6bbc6a', 2, 'verb', null, 'витікати (про рідину)', 'Vandet løber ud af spanden.', 'Вода витікає з відра.'), ('bryde ind', 'phrase', '31aa2bf8-b6a6-530b-b1b4-8393c7ae695b', 1, 'verb', null, 'вламуватися', 'Tyven brød ind i huset om natten.', 'Злодій увірвався в будинок вночі.'), ('bryde ud i', 'phrase', '5420a712-2d79-5560-994f-45eb73dd0ed1', 1, 'verb', null, 'вибухати (сміхом, оплесками тощо)', 'Publikum brød ud i klapsalver.', 'Аудиторія вибухнула оплесками.'), ('næste stop', 'phrase', '5e1a4bdc-eb8e-5f03-9d44-02d8913d70af', 1, 'verb', null, 'наступна зупинка (у транспорті)', 'Næste stop er hovedbanegården.', 'Наступна зупинка — Центральний вокзал.'), ('koncentrere sig', 'phrase', '63dcab2b-f776-54d6-9db3-58c815684af8', 1, 'verb', null, 'зосередитися', 'Jeg kan ikke koncentrere mig, når der er så meget larm.', 'Я не можу зосередитися, коли навколо так багато шуму.'), ('bøde for', 'phrase', 'd01c3d07-ffe8-5c3c-814a-1dbd9be80c1f', 1, 'verb', null, 'розплачуватися (за щось)', 'Han bøder for sine fejl hver dag.', 'Він щодня платить за свої помилки.'), ('gå bort', 'phrase', '76fe24a4-9d85-5868-a63d-ff86150db32e', 1, 'verb', null, 'помирати', 'Min nabo gik bort i sidste uge.', 'Мій сусід помер минулого тижня.'), ('være ligeglad med', 'phrase', '8a6b580c-9b97-58e5-b4cd-a6e483df3634', 1, 'verb', null, 'бути байдужим до', 'Jeg er ligeglad med, hvad de andre tænker.', 'Мені байдуже, що думають інші.'), ('skjule sig', 'phrase', '44117296-28f2-519c-99bb-6244b9c4b11d', 1, 'verb', null, 'ховатися', 'Katten skjuler sig under bordet.', 'Кіт ховається під столом.'), ('hilse på', 'phrase', '7073886d-9eb5-5325-ba14-1728cb54c62f', 1, 'verb', null, 'вітатися (при зустрічі)', 'Jeg hilser på min nabo hver morgen.', 'Щоранку я вітаюся з сусідом.'), ('sige op', 'phrase', '9786a514-1216-557d-b34c-4634ac5f97b8', 1, 'verb', null, 'звільнятися (з роботи)', 'Hun sagde op i går.', 'Вона звільнилася вчора.'), ('samle på', 'phrase', '5c277298-ef87-55e0-a06f-9b6b93667229', 1, 'verb', null, 'колекціонувати', 'Min bedstefar samler på gamle mønter.', 'Мій дідусь збирає старі монети.'), ('redde liv', 'phrase', 'f3fe99c4-383d-5c02-8cf4-6ca3fa98521b', 1, 'verb', null, 'рятувати життя', 'Lægen reddede liv på hospitalet i nat.', 'Минулої ночі лікар рятував життя в лікарні.'), ('basere på', 'phrase', '56f795d2-2f02-51e5-84ad-6c2fdf0b0461', 1, 'verb', null, 'ґрунтувати(ся) на', 'Filmen er baseret på en sand historie.', 'Фільм заснований на реальній історії.'), ('kende til', 'phrase', '2bbbbd4d-2279-5a9a-8de2-149dee724568', 1, 'verb', null, 'знати (про існування)', 'Jeg kender til en god restaurant i nærheden.', 'Я знаю хороший ресторан поруч.'), ('frygte for', 'phrase', 'c49ebdfe-be32-55a0-bab7-d279b0dc5f9d', 1, 'verb', null, 'боятися за', 'Jeg frygter for hans helbred efter ulykken.', 'Я боюся за його здоров''я після аварії.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'uk'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'uk', text, pos, gender, example, example_translation, 'pipeline-phrases-0003' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
